136	  // A tag entry with no pattern would deploy on every tag in the repository, which is
137	  // never what someone meant to write and is expensive to discover. A merge entry with
138	  // no branch is the opposite: it is the ordinary case, and it means the default
139	  // branch.
140	  if (required && patterns.length === 0) {
141	    problems.push(`${where}: \`${key}\` needs at least one pattern — e.g. ["v*"].`);
142	    return null;
